        indegrees[v]--;
        if (indegrees[v] == 0) {
          queue.add(v);
        }
      }
    }
  }

  if (topologicalSort.length != n) {
    print('Graph contains a cycle, topological sort not possible.');
  } else {
    print('Topological Sort: ${topologicalSort.join(' -> ')}');
  }
