List<int> fn0(List<int> phaseDurations, int maxSegmentDuration) {
  if (phaseDurations.isEmpty || maxSegmentDuration <= 0) {
    return [];
  }

  final segments = <List<int>>[];
  int i = 0;
  while (i < phaseDurations.length) {
    final duration = phaseDurations[i];
    if (duration > maxSegmentDuration) {
      i++;
      continue;
    }
    int start = i;
    bool hasGap = false;
    while (i < phaseDurations.length && phaseDurations[i] <= duration) {
      hasGap = true;
      i++;
    }
    if (hasGap) {
      segments.add([start, i - 1]);
    }
  }

  segments.sort((a, b) {
    final durationA = phaseDurations[a[0]];
    final durationB = phaseDurations[b[0]];
    if (durationA != durationB) {
      return durationB.compareTo(durationA);
    }
    return a[1].compareTo(b[1]);
  });

  final result = <int>[];
  int currentStart = segments[0][0];
  int currentEnd = segments[0][1];
  result.add(currentStart);
  for (int j = 1; j < segments.length; j++) {
    if (segments[j][0] >= currentEnd) {
      currentStart = currentEnd;
      currentEnd = segments[j][1];
      result.add(currentStart);
      result.add(currentEnd);
    } else {
      currentEnd = segments[j][1];
    }
  }
  result.add(currentEnd);
  return result;
}

