bool _canSegment(String word, List<String> dictionary) {
  if (dictionary.isEmpty) return false;
  Set<String> dictionarySet = dictionary.toSet();
  List<bool> dp = List.filled(word.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && dictionarySet.contains(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[word.length];
}

List<String> _allSegmentations(String word, List<String> dictionary) {
  if (dictionary.isEmpty) return [];
  Set<String> dictionarySet = dictionary.toSet();
  List<String> segmentations = [];
  List<bool> dp = List.filled(word.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && dictionarySet.contains(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  if (!dp[word.length]) return [];

  List<List<int>> matches = [];
  for (int i = 0; i <= word.length; i++) {
    if (dp[i]) {
      matches.add([i, word.length - i]);
    }
  }

  for (var match in matches) {
    String segment = word.substring(match[0], match[1] + 1);
    segmentations.add(segment);
  }
  return segmentations;
}

int _minWordBreaks(String word, List<String> dictionary) {
  if (dictionary.isEmpty) return 0;
  Set<String> dictionarySet = dictionary.toSet();
  List<int> dp = List.filled(word.length + 1, 0);
  dp[0] = 0; 

  for (int i = 1; i <= word.length; i++) {
    int minBreaks = word.length + 1;
    for (int j = 0; j < i; j++) {
      if (dictionarySet.contains(word.substring(j, i))) {
        int breaksSoFar = dp[j] + 1;
        if (breaksSoFar < minBreaks) {
          minBreaks = breaksSoFar;
        }
      }
    }
    dp[i] = minBreaks;
  }
  return dp[word.length];
}

