      print(path);
      return;
    }
    if (memo.containsKey(word.substring(idx, idx + 1))) {
      bool hasPrefix = memo[word.substring(idx, idx + 1)];
      if (hasPrefix == true) {
        printWordBreak(word, path + word.substring(idx, idx + 1), memo, idx + 1);
      }
    } else {
      for (int i = 0; i <= word.length - idx; i++) {
        bool hasPrefix = isSafe(word, path + word.substring(idx, idx + i), idx + i);
