  List<int> dp = List.filled(n + 1, n + 1);
  dp[0] = 0;
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      String prefix = wordSet[j];
      if (dp[j] == n + 1) continue;
      if (wordSet[i - j - 1] == prefix) {
        dp[i] = dp[i] < dp[j] + 1 ? dp[i] : dp[j] + 1;
      }
