void fn0() {

  final words = {'leet', 'code', 'dog', 'and', 'cat', 'leetcode', 'applepen', 'pen'};

  final str = 'leetcode';
  final str2 = 'applepenapple';

  bool canSegment(String s, Set<String> wordDict) {
    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true; 

    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && wordDict.contains(s.substring(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }
    return dp[s.length];
  }

  List<List<int>> wordBreakII(String s, Set<String> wordDict) {
    Map<String, List<int>> memo = {};
    List<List<int>> result = [];

    List<int> segment(String s, int start, Set<String> wordDict) {
      if (s.isEmpty) return [0];

      if (memo.containsKey(s)) {
        return memo[s]!;
      }

      List<int> segments = [];
      for (int end = 0; end < s.length; end++) {
        for (int i = start; i <= end; i++) {
          if (wordDict.contains(s.substring(i, end + 1))) {
            List<int> sub = segment(s.substring(i, end + 1), i + 1, wordDict);
            for (int len in sub) {
              segments.add(len);
            }
          }
        }
      }
      memo[s] = segments;
      return segments;
    }

    segment(s, 0, wordDict);
    return result..addAll(memo[s]!);
  }

  int minWordBreak(String s, Set<String> wordDict, int minLen) {
    if (s.isEmpty) return 0;

    Map<String, int> length = {};

    for (String word in wordDict) {
      if (word.length > minLen) {
        length[word] = word.length;
      }
    }

    List<bool> dp = List.filled(s.length + 1, false);
    dp[0] = true; 

    for (int i = 1; i <= s.length; i++) {
      for (int j = 0; j < i; j++) {
        if (dp[j] && length.containsKey(s.substring(j, i))) {
          dp[i] = true;
          break;
        }
      }
    }

    if (!dp[s.length]) {
      return -1;
    }

    int minCount = s.length + 1;

    for (int end = s.length; end >= 1; end--) {
      if (dp[end - 1]) {
        if (length.containsKey(s.substring(end - 1, end))) {
          int wordLen = length[s.substring(end - 1, end)]!;
          if (wordLen + end - 1 < minCount) {
            minCount = wordLen + end - 1;
          }
        }
      }
    }

    return minCount;
  }

  print('=== Word Break (Can Segment?) ===');
  print('String: "$str", Dictionary: $words');
  print('Can segment: ${canSegment(str, words)}'); 

  print('=== Word Break II (All Segmentations) ===');
  print('String: "$str2", Dictionary: $words');
  print('All possible segmentations:');
  List<List<int>> segs = wordBreakII(str2, words);
  for (var seg in segs) {
    print(seg);
  }

  print('=== Minimum Word Breaks ===');
  print('String: "$str2", Dictionary: $words, Minimum word length: 3');
  print('Minimum words needed: ${minWordBreak(str2, words, 3)}'); 
}

