void fn0() {

  List<String> wordBreak = ['leet', 'code'];
  String sentence = "leetcode";
  Set<String> dictionary = wordBreak.toSet();

  bool canSegment = false;
  int minWords = 0;
  List<String> segmentations = [];

  void backtrack(int index, List<String> current, List<bool> used, List<String> segmentations, int minWords) {
    if (index == sentence.length) {
      if (current.length == minWords) {
        segmentations.add(current.join(' '));
      }
      return;
    }

    for (String word in wordBreak) {
      if (sentence.substring(index, index + word.length) == word) {
        used[index] = true;
        current.add(word);

        backtrack(index + word.length, current, used, segmentations, minWords);

        current.removeLast();
        used[index] = false;
      }
    }
  }

  List<bool> used = List.filled(sentence.length, false);

  for (int i = 0; i < sentence.length; i++) {
    if (!used[i]) {
      List<String> tmp = [];
      backtrack(i, tmp, used, segmentations, minWords);
    }
  }

  print("=== Word Break (Can Segment?) ===");
  canSegment = dictionary.contains(sentence);
  print("Can segment: $canSegment");

  print("=== Minimum Word Breaks ===");
  if (canSegment) {
    minWords = -1;
    for (String word in wordBreak) {
      List<String> tmp = [];
      backtrack(0, tmp, [], segmentations, 1);
      int len = tmp.length;
      if (len < minWords || (len == minWords && tmp.isEmpty)) {
        minWords = len;
      }
    }
    print("Minimum words needed: $minWords");
    print("All possible segmentations:");
    print(segmentations);
  } else {
    print("Cannot segment");
  }

  print("=== Word Break II (All Segmentations) ===");
  List<String> allSeg = [];
  for (String word in wordBreak) {
    List<String> tmp = [];
    backtrack(0, tmp, [], allSeg, 1);
  }
  print(allSeg);
}

