int _calculateTotalCombinations(int n, int k) => _combinations(n, k, 0, n, k, 1);

List<String> _generateCombinations(List<String> items, int k) {
  final List<String> result = [];
  _combinations(items, k, 0, items.length, k, result);
  return result;
}

int _combinations(int n, int k, int start, int itemsLength, int kSize, List<String> result) {
  if (kSize == 0) {
    result.add('');
    return 1;
  }
  if (start >= itemsLength) return 0;

  int currentSubsets = _combinations(n, k - 1, start + 1, itemsLength, kSize - 1, result);

  int remaining = itemsLength - start - (kSize - 1);
  if (remaining < kSize) return currentSubsets;

  for (int i = start; i < itemsLength; i++) {
    String item = items[i];
    result.add(item);
    _combinations(n, k - 1, start + 1, itemsLength, kSize, result);
  }

  return currentSubsets + _combinations(n, k - 1, start + 1, itemsLength, kSize - 1, result);
}

