    print('No args provided. Using default input: k=4, items=${items.join(', ')}');
    items = ['A', 'B', 'C', 'D'];
  }

  final int totalCombinations = _combinations(items.length, k);
  print('Total combinations: $totalCombinations');

  final List<String> combination = _generateCombinations(items, k);
  print('Total combinations: 1');
  print('Items in combination: $combination');
}

int _combinations(int n, int k) {
  if (n == 0 || k == 0 || k > n) return 0;
  if (k == 1) return n;

  int result = 0;
  int i = 0;

  while (i < n) {
    final String current = items[i];
    int j = i + 1;

    while (j < n && items[j] == current) j++;

    final int count = j - i;
    result += count;
    result += (count > 1 ? count - 1 : 0) * _combinations(n - j, k - 1);

    i = j;
  }

  return result;
}

List<String> _generateCombinations(List<String> items, int k) {
  if (items.isEmpty || k == 0) return [];
  if (items.length == 1) {
    return [items[0]];
  }

  final int n = items.length;
  final List<String> result = [];

  for (int i = 0; i < (1 << n); i++) {
    final List<String> current = [];

    for (int j = 0; j < n; j++) {
      if ((i & (1 << j)) != 0) {
        current.add(items[j]);
      }
    }

    if (current.length == k) {
      result.add(current.toString());
    }
  }

  return result;
}

