bool hasPath(int u, int v) {
  if (!graph.containsKey(u) || !graph.containsKey(v)) return false;
  List<int> queue = [u];
  visited[u] = 1;
  while (queue.isNotEmpty) {
    u = queue.removeAt(0);
    if (v == u) return true;
    for (var neighbor in graph[u] ?? []) {
      if (!visited[neighbor]) {
        visited[neighbor] = 1;
        queue.add(neighbor);
      }
    }
  }
  return false;
}

