Set<int> fn0(int maxQueueSize, List<int> operations) {
  Set<int> overflow = {0};
  List<int> queue = [];
  for (int op in operations) {
    if (op == 0) {
      if (queue.isNotEmpty) {
        overflow.add(queue.removeLast());
      }
    } else {
      if (queue.length < maxQueueSize) {
        queue.add(op);
      } else {
        overflow.add(queue.removeAt(0));
        queue.add(op);
      }
    }
  }
  return overflow;
}

