Map<String, int> fn0(List<int> playlist, int maxDuration) {
  if (playlist.isEmpty || maxDuration < 0) {
    return {"pairCount": 0, "mashupDuration": 0};
  }

  int left = 0;
  int mashupDuration = 0;
  int pairCount = 0;

  void search(int right) {
    while (right < playlist.length) {
      while (right < playlist.length &&
          (playlist[right] + playlist[left]) > maxDuration) {
        left++;
      }
      int windowLength = right - left + 1;
      if (windowLength >= 2) {
        mashupDuration += windowLength;
        pairCount += (windowLength - 1);
      }
      right++;
    }
  }

  search(left);

  search(left + 1);

  return {"pairCount": pairCount, "mashupDuration": mashupDuration};
}

