Map<String, int> fn0(List<int> readings, int threshold) {
  if (readings.isEmpty) {
    return {'pairCount': 0, 'mashupDuration': 0};
  }
  int n = readings.length;
  List<int> dp = List<int>.filled(n, 0);
  int maxDuration = 0;
  for (int i = 0; i < n; i++) {
    if (readings[i] >= threshold) {
      dp[i] = (i == 0) ? 1 : 1 + dp[i - 1];
      if (dp[i] > maxDuration) {
        maxDuration = dp[i];
      }
    }
  }
  return {'pairCount': maxDuration, 'mashupDuration': maxDuration * threshold};
}

