    return {'pairCount': 0, 'mashupDuration': 0};
  }
  int pairCount = 0;
  int mashupDuration = 0;
  void search(int left, int right) {
    while (left <= right) {
      int gap = playDays[left] - playDays[left - 1];
      int duration = gap < breakDays ? gap : breakDays;
      if (duration > mashupDuration) mashupDuration = duration;
      pairCount += duration ~/ 2;
      left++;
