class Quaternion {
  double x, y, z, w;

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.unit() : this(1.0, 0.0, 0.0, 1.0);

  const Quaternion.unitX() : this(0.0, 1.0, 0.0, 0.0);

  const Quaternion.unitY() : this(0.0, 0.0, 1.0, 0.0);

  const Quaternion.unitZ() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.inverseUnit() : this(0.0, 0.0, 0.0, -1.0);

  const Quaternion.identity() : this(1.0, 0.0, 0.0, 1.0);

  double get norm => sqrt(x * x + y * y + z * z + w * w);

  double get real => x + y + z + w;

  double get imaginary => x * y + z * w;

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion normalized() {
    final n = norm;
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion inverse() {
    if (norm == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    final n = norm;
    return Quaternion(x / n, y / n, z / n, -w / n);
  }

  Quaternion operator +(const Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(const Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator * (const Quaternion other) {
    final tx = x * other.w, ty = y * other.w, tz = z * other.w;
    final wx = x * other.z, wy = y * other.z, wz = z * other.z;
    final xx = x * x, yy = y * y, zz = z * z;
    return Quaternion(
      tx * other.y - ty * other.z,
      ty * other.x + tx * other.z,
      tz * other.y - ty * other.x,
      xx * other.w + yy * other.w + zz * other.w
    );
  }

  Quaternion operator * (final double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar
    );
  }

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

