  const Quaternion.zero => const Quaternion(0, 0, 0, 0);

  const Quaternion.pureImaginary => const Quaternion(0, 0, 0, 1);

  const Quaternion.pureReal => const Quaternion(1, 0, 0, 0);

  const Quaternion.fromList(List<double> parts)
      : q0 = parts[0],
        q1 = parts[1],
        q2 = parts[2],
        q3 = parts[3];

  const Quaternion.fromComplex(double r, double i)
      : q0 = r,
        q1 = i,
        q2 = 0,
        q3 = 0;

  @override
  bool operator ==(Object other) =>
      other is Quaternion &&
      q0 == other.q0 &&
      q1 == other.q1 &&
      q2 == other.q2 &&
      q3 == other.q3;

  @override
  int get hashCode => q0.hashCode ^ q1.hashCode ^ q2.hashCode ^ q3.hashCode;

  bool get isUnit => q0 == 1 && q1 == 0 && q2 == 0 && q3 == 0;

  bool get isZero => q0 == 0 && q1 == 0 && q2 == 0 && q3 == 0;

  bool get isImaginary => q0 == 0 && q1 != 0 && q2 == 0 && q3 == 0;

  bool get isReal => q0 != 0 && q1 == 0 && q2 == 0 && q3 == 0;

  double get norm => q0 * q0 + q1 * q1 + q2 * q2 + q3 * q3;

  double get magnitude => sqrt(norm);

  Quaternion conjugate() =>
      const Quaternion(q0, -q1, -q2, -q3);

  Quaternion inverse() =>
      const Quaternion(q0, -q1, -q2, -q3) / norm;

  Quaternion normalized() =>
      const Quaternion(q0 / norm, q1 / norm, q2 / norm, q3 / norm);

  Quaternion operator +(Object other) =>
      other is Quaternion
          ? const Quaternion(q0 + other.q0, q1 + other.q1, q2 + other.q2, q3 + other.q3)
          : other;

  Quaternion operator -(Object other) =>
      other is Quaternion
          ? const Quaternion(q0 - other.q0, q1 - other.q1, q2 - other.q2, q3 - other.q3)
          : other;

  Quaternion operator *(Object other) =>
      other is Quaternion
          ? const Quaternion(
              q0 * other.q0 - q1 * other.q1 - q2 * other.q2 - q3 * other.q3,
              q0 * other.q1 + q1 * other.q0 + q2 * other.q3 - q3 * other.q2,
              q0 * other.q2 + q2 * other.q0 - q3 * other.q1 + q1 * other.q3,
              q0 * other.q3 + q3 * other.q0 + q1 * other.q2 - q2 * other.q1)
          : other;

  double *toComplexArray() => [q0, q1, q2, q3];

  @override
  String toString() {
    if (isZero) return '0';
    if (isReal) return '$q0';
    if (isImaginary) return '${q1}i';
    final parts = <String>[];
    if (q3 > 0) parts.add(q3.toString());
    if (q2 != 0) parts.add(q2.toString());
    if (q1 != 0) parts.add(q1.toString());
    if (q0 != 0) parts.add(q0.toString());
    return parts.join(' + ');
  }
}

