class Quaternion {
  double x, y, z, w;

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.random() : this(
    Random(0).nextDouble() * 2 - 1.0,
    Random(0).nextDouble() * 2 - 1.0,
    Random(0).nextDouble() * 2 - 1.0,
    Random(0).nextDouble() * 2 - 1.0,
  );

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
        x * other.w - y * other.z - z * other.y + w * other.x,
        y * other.w + x * other.z - z * other.y + w * other.y,
        z * other.w + y * other.x - x * other.z + w * other.z,
        w * other.w - x * other.x - y * other.y - z * other.z,
      );

  Quaternion operator ~/Quaternion(Quaternion other) =>
      Quaternion(
        (x * other.w + y * other.z + z * other.y) ~/ (other.w * other.w + other.z * other.z),
        (y * other.w - x * other.z) ~/ (other.w * other.w + other.z * other.z),
        (z * other.w - y * other.x) ~/ (other.w * other.w + other.z * other.z),
        (w * other.w - x * other.x - y * other.y - z * other.z) ~/
            (other.w * other.w + other.z * other.z),
      );

  Quaternion conjugate() =>
      Quaternion(x, y, z, -w);

  double norm() =>
      sqrt(x * x + y * y + z * z + w * w);

  double norm2() =>
      x * x + y * y + z * z + w * w;

  Quaternion normalized() =>
      if (norm() == 0.0) Quaternion.zero()
      else
        this ~/ norm();

  Quaternion inverse() =>
      if (norm() == 0.0) Quaternion.zero()
      else
        conjugate() ~/ norm2();

  Quaternion rotateZ(double angle) =>
      Quaternion(
        x * cos(angle) - z * sin(angle),
        y * sin(angle) + z * cos(angle),
        z * cos(angle) + x * sin(angle),
        w,
      );

  @override
  String toString() =>
      'q1 = $x + $y * i + $z * j + $w * k';
}

