class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.one() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.fromList(List<double> list)
      : x = list[0],
        y = list[1],
        z = list[2],
        w = list[3];

  const Quaternion.fromAxisAngle(
    List<double> axis,
    double angle,
  ) : x = axis[0] * cos(angle / 2),
        y = axis[1] * sin(angle / 2),
        z = axis[2] * sin(angle / 2),
        w = axis[3] * cos(angle / 2);

  const Quaternion.fromComplex(
    List<double> complex,
  ) : x = complex[0] + complex[1],
        y = complex[0] - complex[1],
        z = complex[2] + complex[3],
        w = complex[2] - complex[3];

  double norm() {
    double a = x, b = y, c = z, d = w;
    return sqrt(a * a + b * b + c * c + d * d);
  }

  Quaternion normalized() {
    final double norm = norm();
    if (norm == 0.0) return const Quaternion.zero();
    return const Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion conjugate() {
    return const Quaternion(x, y, z, -w);
  }

  Quaternion invert() {
    final double norm = norm();
    if (norm == 0.0) return const Quaternion.zero();
    return const Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion operator*(Quaternion other) {
    return const Quaternion(
        x * other.w - y * other.z - z * other.y + w * other.x,
        y * other.w + x * other.z - z * other.y + w * other.y,
        z * other.w + w * other.x - x * other.y + y * other.z,
        w * other.w - x * other.x - y * other.y - z * other.z);
  }

  @override
  String toString() {
    return 'q1 = ${x.toStringAsFixed(2)} + ${y.toStringAsFixed(2)}i + '
        '${z.toStringAsFixed(2)} + ${w.toStringAsFixed(2)}j';
  }
}

