  Quaternion operator -(Quaternion other) const Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) const Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) const Quaternion(
    (w * other.w - x * other.x - y * other.y - z * other.z),
    (w * other.x + x * other.w + y * other.z - z * other.y),
    (w * other.y + x * other.z + y * other.w - z * other.x),
    (w * other.z - x * other.y - y * other.x - z * other.w),
  );

  Quaternion inverse() const Quaternion(x, y, z, -w);

  Quaternion conjugate() const Quaternion(x, y, z, w);

  double norm() const sqrt(x * x + y * y + z * z + w * w);

  Quaternion normalized() const {
    final n = norm();
    return Quaternion(x / n, y / n, z / n, w / n);
  }

