Map<String, int> fn0(List<int> rolls, int targetSum) {
  if (rolls.isEmpty || targetSum <= 0) {
    return {};
  }

  List<int> dp = List.filled(rolls.length + 1, 0);
  for (int i = 1; i <= rolls.length; i++) {
    dp[i] = dp[i - 1] + rolls[i - 1];
  }

  Map<String, int> result = {};
  int left = 0;
  int right = rolls.length;
  while (left < right) {
    int mid = left + ((right - left) >> 1);
    if (dp[mid] < targetSum) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int start = left;
  if (dp[start] == targetSum) {
    result["${start}:${start + 1}"] = dp[start];
  }

  int end = start + 1;
  while (end <= rolls.length) {
    if (dp[end] == targetSum) {
      result["${start + 1}:${end}"] = dp[start];
      start = end;
    } else {
      end++;
    }
  }
  return result;
}

