    {"text": "AABAACAADAABAABA", "pattern": "AAABAAA"},
    {"text": "AABAACAADAABAABA", "pattern": "AAAA"},
  ];

  void bruteForceSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    List<List<bool>> dp = List.generate(n + 1, (_) => List.filled(m + 1, false));

    for (int i = 0; i <= n; i++) dp[i][0] = true;
    for (int j = 0; j <= m; j++) dp[0][j] = true;

    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= m; j++) {
        if (pattern[j - 1] == text[i - 1]) {
          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = dp[i - 1][j];
        }
      }
    }

    print("\nText: $text");
    print("Pattern: $pattern");
    print("Pattern length: $patternLen");
    print("\nLPS array for pattern: $pattern");
    print("Matches at: ${dp[n][m]}");
  }

  void kmpSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    List<int> lps = List.filled(m + 1, 0);
    int i = 1;
    int len = 0;

    while (i <= m) {
      if (pattern[i - 1] != 0) lps[i] = len;
      else {
        if (i > 1) len = len - 1;
        else len = 0;
        i++;
      }
    }

    for (int i = 1; i <= n; i++) {
      int j = i - 1;
      while (j >= 1 && pattern[j] != text[i - 1]) {
        j--;
      }
      if (j >= 1 && pattern[j] == text[i - 1]) {
        int k = j - 1;
        while (k >= 0 && pattern[k] == text[i - 1]) {
          k--;
        }
        if (k >= 0 && lps[k + 1] >= len) {
          print("Pattern found at indices: $i");
          len = len + 2 - k;
        } else {
          print("Pattern not found at index $i");
          len = len + 1;
        }
      } else {
        print("Pattern not found at index $i");
        len = len + 1;
      }
    }
  }

  void kmpSearchWithLPS(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    List<int> lps = List.filled(m + 1, 0);
    int i = 1;
    int len = 0;

    while (i <= m) {
      if (pattern[i - 1] != 0) lps[i] = len;
      else {
        if (i > 1) len = len - 1;
        else len = 0;
        i++;
      }
    }

    int state = 0;

    for (int i = 0; i <= n; i++) {
      if (state == 0) {
        if (text[i] == pattern[0]) {
          for (int j = 1; j <= m; j++) {
            if (text[i] == pattern[j - 1]) {
              state = j;
              break;
            }
          }
        }
      } else {
        if (text[i] == pattern[state - 1]) {
          state++;
        } else if (state > 1) {
          state = 1;
        } else {
          break;
        }
      }
    }

    if (state == m + 1) {
      print("Pattern not found at index $0");
    } else {
      print("Pattern found at indices: ${state - 1}");
    }
  }

