    String pattern = testCase["pattern"];

    print("\n--- Additional Test Cases ---");
    print("Text: $text");
    print("Pattern: $pattern");

    if (pattern.length >= 10) {
      bruteForceSearch(text, pattern);
    } else {
      kmpSearch(text, pattern);
    }
  }

