  } else {
    kmpSearch(exampleText, examplePattern);
  }

  print("\nText: 'AABAACAADAABAABA', Pattern: 'A'");
  kmpSearch(exampleText, "A");

  print("\nText: 'AABAACAADAABAABA', Pattern: 'AA'");
  kmpSearch(exampleText, "AA");

  print("\nText: 'AABAACAADAABAABA', Pattern: 'AAA'");
  kmpSearch(exampleText, "AAA");

