  }
  int total = rows * cols;
  if (total < 3) {
    return rows > 1 ? precinctVotes[0][0] > threshold ? 1 : 0 : 0;
  }
  int mid = total ~/ 2;
  int left = 0;
  int right = mid;
  while (left < right) {
    int pivot = (left + right) ~/ 2;
    int sum = 0;
    for (int i = 0; i < rows; i++) {
      int start = i * cols;
      int end = start + pivot;
      for (int j = start; j < end; j++) {
        sum += precinctVotes[i][j];
      }
    }
    if (sum > threshold) {
      right = pivot;
    } else {
      left = pivot + 1;
    }
  }
  return rows > 1 ? left > 1 ? left : 1 : left == 1 ? precinctVotes[0][0] > threshold ? 1 : 0 : 0;
}

