int fn0(List<int> p0, int p1) {
  List<int> dp = List.filled(p0.length + 1, 0);
  for (int i = 0; i <= p0.length; i++) {
    if (i == 0) {
      dp[i] = p1;
    } else if (i < p0.length) {
      int val = p0[i - 1];
      int up = dp[i - 1] + val * 2;
      int down = dp[i - 1] + val;
      if (up > down) {
        dp[i] = up;
      } else {
        dp[i] = down;
      }
    } else {
      dp[i] = dp[i - 1] + p1;
    }
  }
  return dp[p0.length];
}

