int fn0(List<int> packetSizes, int mtu) {
  if (packetSizes.isEmpty || mtu <= 0) return 0;
  List<int> dp = List.filled(packetSizes.length + 1, 0);
  dp[0] = mtu;
  for (int i = 1; i <= packetSizes.length; i++) {
    int windowSize = packetSizes[i - 1];
    if (windowSize > mtu) continue;
    int left = 0, right = i - 1;
    while (left < right) {
      int mid = (left + right) ~/ 2;
      if (dp[mid] >= windowSize) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }
    if (left > 0) {
      int space = dp[left - 1] - windowSize;
      dp[i] = dp[i] < space ? dp[i] : space;
    } else {
      dp[i] = dp[i - 1] - windowSize;
    }
  }
  return dp[packetSizes.length];
}

