int fn0(List<int> rows, int cols) {
  var dp = List.filled(rows.length + 1, 0);
  for (var r = 0; r < rows.length; r++) {
    var c = rows[r];
    dp[r + 1] = dp[r] + c * (c - 1) ~/ 2 + c;
  }
  var best = 0;
  for (var c = 1; c <= cols; c++) {
    var sum = 0;
    for (var r = 0; r < rows.length; r++) {
      if ((r + 1) % c == 0) sum += rows[r];
    }
    if (sum > best) best = sum;
  }
  return best;
}

