void fn0() {



  final userRoles = <String, List<int>>{
    'alice': [1, 2, 4],
    'bob': [1, 2, 3, 4],
    'charlie': [1, 3],
  };

  final roles = <String, List<String>>{
    'admin': ['read', 'write', 'delete', 'admin'],
    'editor': ['read', 'write'],
    'viewer': ['read'],
  };

  final resources = <String, List<String>>{
    'document1': ['read', 'write'],
    'document2': ['read'],
    'sensitive_data': ['read', 'write'],
  };

  final permissions = <String, List<String>>{
    'read': ['view', 'edit'],
    'write': ['edit', 'delete'],
    'delete': ['delete'],
    'admin': [],
  };

  final users = <String, Map<String, dynamic>>{
    'alice': {'name': 'Alice', 'email': 'alice@example.com'},
    'bob': {'name': 'Bob', 'email': 'bob@example.com'},
  };

  final resourceAccessMatrix = <String, List<String>>{};
  final userPermissions = <String, List<String>>{};

  void assignRole(String user, String role) {
    userRoles[user] = roles[role] ?? [];
    print('Elevating $user to $role role...');
  }

  void grantPermission(String user, String resource, String action) {
    var role = action == 'admin' ? 'admin' : action;
    var permission = permissions[action] ?? [];
    if (permission.contains(resource)) {
      userRoles[user] ??= <int>[];
      userRoles[user]!.add(permissions[action]!.indexOf(resource));
      print('  ➜ Access GRANTED (Role: $role)');
    } else {
      print('  ➜ Access DENIED (Insufficient permissions)');
    }
  }

  void denyPermission(String user, String resource, String action) {
    var role = action == 'admin' ? 'admin' : action;
    var permission = permissions[action] ?? [];
    if (permission.contains(resource)) {
      userRoles[user] ??= <int>[];
      userRoles[user]!.remove(permissions[action]!.indexOf(resource));
      print('  ➜ Access DENIED (Role: $role)');
    } else {
      print('  ➜ Access DENIED (Insufficient permissions)');
    }
  }

  void listResources(String role) {
    print('Role: $role');
    for (var resource in resources.keys) {
      var permissions = roles[role] ?? [];
      if (permissions.contains(resource)) {
        print('  $resource');
      }
    }
  }

  void listUsersWithPermission(String action) {
    print('Permissions: $action');
    userRoles.forEach((user, roles) {
      if (roles.isNotEmpty) {
        print('  ${user.padRight(10)} → ${roles.join(', ')}');
      }
    });
  }

  void listRolesWithUser(String user) {
    print('User: $user');
    userRoles[user]?.forEach((r) => print('  - ${roles['$r']}'));
  }

  void listUserPermissions(String user) {
    print('Permissions:');
    for (var action in ['read', 'write', 'delete', 'admin']) {
      if (userRoles[user]?.contains(permissions[action]!.indexOf('view')) ?? false) {
        print('  $action → ${permissions[action]!.join(', ')}');
      }
    }
  }

  String getCurrentRole(String user) {
    if (userRoles.containsKey(user)) {
      var roles = userRoles[user]!;
      if (roles.length == 1) {
        return roles[0].toString();
      }
      var roleNames = roles.map((r) => roles['$r']).toList();
      return roleNames.join('-').padRight(10);
    }
    return 'User not found';
  }

  void grantResource(String user, String resource, String action) {
    grantPermission(user, resource, action);
  }

  void denyResource(String user, String resource, String action) {
    denyPermission(user, resource, action);
  }

  void listAccessMatrix(String resource) {
    print('User/Resource Access Matrix:');
    resourceAccessMatrix.forEach((user, permissions) {
      if (permissions.contains(resource)) {
        print('  ${user.padRight(10)} → ${permissions.join(', ')}');
      }
    });
  }

  void logAccess(String user, String resource, String action) {
    String timestamp = DateTime.now().toString();
    print('➜ ${timestamp.padRight(18)} | ${user.padRight(10)} | ${action.padRight(10)} | ${resource}');
  }

  void displaySystemSummary() {
    print('\n=== System Summary ===');
    print('Total Users: ${users.length}');
    print('Total Resources: ${resources.length}');
    print('Total Roles: ${roles.length}');
    print('Total Permissions: ${permissions.length}');
  }

  void displayRecentAccessAttempts() {
    print('\nRecent Access Attempts:');
    for (var entry in userRoles.entries) {
      String user = entry.key;
      var roles = entry.value;
      if (roles.length > 1) {
        print('  ${user.padRight(10)} → ${roles.join(', ')}');
      } else {
        print('  ${user.padRight(10)} → ${roles[0]}');
      }
    }
  }

  print('=== Role-Based Access Control System ===');
  print('============================================');

  void testAccessControl() {

    var user = 'alice';
    print('\nAttempting to access admin resource...');
    grantResource(user, 'sensitive_data', 'read');
    print('  ➜ Access granted');
    denyResource(user, 'sensitive_data', 'write');
    print('  ➜ Access denied');

    var editor = 'bob';
    print('\n' + '=' * 30);
    print('Current role for $editor: ${getCurrentRole(editor)}');
    grantResource(editor, 'document1', 'write');
    print('  ➜ Access granted');
    denyResource(editor, 'document1', 'delete');
    print('  ➜ Access denied');

    var viewer = 'charlie';
    print('\n' + '=' * 30);
    print('Current role for $viewer: ${getCurrentRole(viewer)}');
    grantResource(viewer, 'document2', 'view');
    print('  ➜ Access granted');
    denyResource(viewer, 'document2', 'edit');
    print('  ➜ Access denied');
  }

  testAccessControl();

  print('\n--- User Permissions Overview ---');
  listUserPermissions('alice');
  listUserPermissions('bob');
  listUserPermissions('charlie');

  print('\n--- Resource Access Matrix ---');
  listAccessMatrix('sensitive_data');
  listAccessMatrix('document1');
  listAccessMatrix('document2');

  print('\n--- Permission Inheritance Demo ---');
  assignRole('alice', 'editor');
  listResources('editor');

  print('\n--- Access Control Tests ---');
  testAccessControl();

  print('\n--- Audit Log ---');
  logAccess('alice', 'sensitive_data', 'read');
  logAccess('bob', 'document1', 'write');
  logAccess('charlie', 'document2', 'view');

  displayRecentAccessAttempts();

  print('\n--- Permission Elevation Scenario ---');
  assignRole('bob', 'admin');
  print('Elevated ${getCurrentRole("bob")} → ${getCurrentRole("bob")}!');

  print('\n=== System Summary ===");
  displaySystemSummary();
}

import 'dart:async';
import 'dart:convert';
@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  const String user1 = 'alice';
  const String user2 = 'bob';
  const String user3 = 'charlie';
  const String user4 = 'diana';

  const String role1 = 'admin';
  const String role2 = 'moderator';
  const String role3 = 'editor';
  const String role4 = 'viewer';

  const String resource1 = 'document1';
  const String resource2 = 'document2';
  const String resource3 = 'sensitive_data';

  const String action1 = 'read';
  const String action2 = 'write';
  const String action3 = 'delete';
  const String action4 = 'admin';

  Map<String, List<String>> userRoles = {
    user1: [role1, role3],
    user2: [role2, role4],
    user3: [role4],
  };

  Map<String, List<String>> rolePermissions = {
    role1: [action1, action2, action3, action4],
    role2: [action1, action2, action3],
    role3: [action1, action2],
    role4: [action1],
  };

  Map<String, List<List<String>>> resourcePermissions = {
    resource1: [action1, action2],
    resource2: [action1, action2],
    resource3: [action1, action2, action3],
  };

  Map<String, String> currentRoles = {
    user1: role1,
    user2: role2,
    user3: role4,
  };

  Map<String, String> auditLog = {};

  Map<String, List<String>> _applyPermissions(String user, List<String> roles) {
    Map<String, String> permissions = {};
    for (String role in roles) {
      Map<String, List<String>> rolePermissions =
          rolePermissions[role] ?? Map<String, List<String>>();
      for (String resource in rolePermissions.keys) {
        if (rolePermissions[resource]!.contains(action1)) {
          permissions[resource] = (permissions[resource] ?? '') + ', ';
        }
      }
    }
    if (permissions.isEmpty) return {};
    return permissions;
  }

  String _applyPermissionsStr(String user, List<String> roles) {
    StringBuffer sb = StringBuffer();
    bool first = true;
    for (String role in roles) {
      Map<String, List<String>> rolePermissions =
          rolePermissions[role] ?? Map<String, List<String>>();
      for (String resource in rolePermissions.keys) {
        if (rolePermissions[resource]!.contains(action1)) {
          if (!first) sb.write(' ');
          sb.write(resource);
        }
      }
      first = false;
    }
    return sb.toString();
  }

  void _grantPermissions(String user, List<String> roles) {
    Map<String, String> newPermissions =
        _applyPermissions(user, roles) ?? Map<String, String>();
    currentRoles[user] = _findHighestRole(newPermissions);
    auditLog[user] = 'Permissions granted: ${newPermissions.keys.toList()}';
  }

  String _findHighestRole(Map<String, String> permissions) {
    String highestRole = '';
    int maxCount = 0;
    for (String resource in permissions.keys) {
      int count = permissions[resource]!.split(',').length - 1;
      if (count > maxCount) {
        maxCount = count;
        highestRole = resource;
      } else if (count == maxCount && resource.length > highestRole.length) {
        highestRole = resource;
      }
    }
    return highestRole;
  }

  void _audit(String user, String action, String resource) {
    auditLog[user] = (auditLog[user] ?? '')
        .isEmpty ? action : '${auditLog[user]} ${action.padRight(13)}';
  }

  bool _checkPermission(String user, String resource, String action) {
    String userRole = currentRoles[user] ?? '';
    Map<String, List<String>> rolePermissions =
        rolePermissions[userRole] ?? Map<String, List<String>>();
    if (!rolePermissions.containsKey(resource)) {
      return false;
    }
    return rolePermissions[resource]!.contains(action);
  }

  print('=== Role-Based Access Control System ===\n');

  print('User/Resource Access Matrix:\n');
  for (String user in userRoles.keys) {
    String role = currentRoles[user] ?? '';
    print('  ${user} -> ${role}');
  }

  print('\n--- Access Control Tests ---\n');

  bool accessAllowed = _checkPermission(user1, resource1, action1);
  print('Attempting to access ${resource1}: ${accessAllowed ? "✅" : "❌"}'); 

  accessAllowed = _checkPermission(user1, resource1, action2);
  print('Attempting to write to ${resource1}: ${accessAllowed ? "✅" : "❌"}'); 

  accessAllowed = _checkPermission(user1, resource1, action3);
  print('Attempting to delete ${resource1}: ${accessAllowed ? "✅" : "❌"}'); 

  accessAllowed = _checkPermission(user3, resource1, action1);
  print('Attempting to read from ${resource1}: ${accessAllowed ? "✅" : "❌"}'); 

  _grantPermissions(user3, [role2, role4]);
  accessAllowed = _checkPermission(user3, resource1, action1);
  print('Elevating ${user3} to ${role2}: ${accessAllowed ? "✅" : "❌"}'); 

  accessAllowed = _checkPermission(user3, resource1, action1);
  print('Current role for ${user3}: ${currentRoles[user3]}'); 

  _audit(user1, 'Edit', resource1);

  print('\n--- Permission Inheritance Demo ---\n');

  Map<String, List<String>> combinedRoles = [
    role1, role2, role3, role4,
  ];
  Map<String, String> combinedPermissions =
      _applyPermissions(user1, combinedRoles) ?? Map<String, String>();
  print('New role for ${user1}: ${combinedPermissions.keys.toList()}'); 

  print('\n--- User Permissions Overview ---\n');
  print('Total Users: ${userRoles.length}\n');
  for (String user in userRoles.keys) {
    print('User: ${user}');
    List<String> roles = userRoles[user] ?? [];
    print('Roles: ${roles.toList()}');
    print('Permissions: ${combinedPermissions[user]}');
  }

  print('\n--- Resource Access Matrix ---\n');
  print('Total Resources: ${resourcePermissions.length}\n');
  for (String resource in resourcePermissions.keys) {
    Map<String, List<String>> rolePermissions =
        resourcePermissions[resource] ?? Map<String, List<String>>();
    String roleStr = _applyPermissionsStr(user1, [role1, role2, role3]);
    print('  ${resource} -> ${roleStr}');
  }

  print('\n--- Audit Log ---\n');
  for (String user in auditLog.keys) {
    print('  ${user}: ${auditLog[user]}');
  }

  print('\n=== System Summary ===\n');
  print('Total Roles: ${rolePermissions.length}\n');
  for (String role in rolePermissions.keys) {
    print('  ${role}: ${rolePermissions[role].length} actions');
  }

  print('Total Permissions: ${rolePermissions.values.fold(0, (a, b) => a + b)}\n');

  print('Recent Access Attempts:\n');
  for (String user in auditLog.keys) {
    String log = auditLog[user] ?? '';
    if (log.isNotEmpty) {
      print('  ${user} attempts to ${log.split(' ')[0]}: ${log.split(' ')[1]}');
    }
  }

  print('\n--- Permission Elevation Scenario ---\n');

  Map<String, String> elevated = {
    user2: 'admin',
  };
  currentRoles.updateAll(elevated);

  bool accessAdmin = _checkPermission(user2, resource3, action4);
  print('Attempting to access ${resource3}: ${accessAdmin ? "✅" : "❌"}'); 
}

