bool fn0(List<int> schedule, int targetMinute) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  if (schedule.isEmpty) return false;
  if (schedule.length % 3 != 0) return false;
  if (targetMinute < 0) return false;

  Set<int> activeMinutes = {};
  for (int i = 0; i < schedule.length; i += 3) {
    int start = schedule[i];
    int end = schedule[i + 1];
    int duration = schedule[i + 2];

    if (start < 0 || end < 0 || duration <= 0) return false;

    if (duration > end - start) {
