    }

    if (gcd(duration, end - start) != 1) {
      return false;
    }

    if (duration > 0) {
      activeMinutes.add(start);
      activeMinutes.add(end);
    }
  }

  if (activeMinutes.isEmpty) return false;

  int g = 0;
  for (int minute in activeMinutes) {
    g = gcd(g, minute);
  }

  if (g == 0) return false;

  for (int minute = 0; minute < 60; minute++) {
    if (gcd(minute, targetMinute) != 1) {
      continue;
    }

    bool isPrime = true;
    for (int d = 2; d * d <= minute; d++) {
      if (minute % d == 0) {
        isPrime = false;
        break;
      }
    }

    if (!isPrime) continue;

    if (activeMinutes.contains(minute)) {
      return true;
    }
  }

  return false;
}

