          b = a % b;
          a = t;
        }
        if (a == 1) {
          uniqueUnits.add(d);
          break;
        }
      }
    }
  }
  if (uniqueUnits.length < 2) return false;
  final int g = cents.isEmpty ? 0 : cents[0];
  for (final int u in uniqueUnits) {
    for (final int c in roundedCents) {
      if (gcd(g, u) == 1) {
